import{r as e}from"./auth-bgkSYldb.js";var t={providers(){return e.get(`/auth/oauth/providers`)},discoverSSO(t){return e.post(`/auth/oauth/discover`,{email:t})},linkedAccounts(){return e.get(`/users/me/oauth`)},unlink(t){return e.delete(`/users/me/oauth/${t}`)},adminList(){return e.get(`/admin/oauth/providers`)},adminCreate(t){return e.post(`/admin/oauth/providers`,t)},adminUpdate(t,n){return e.put(`/admin/oauth/providers/${t}`,n)},adminDelete(t){return e.delete(`/admin/oauth/providers/${t}`)},getSSO(){return e.get(`/workspaces/current/sso`)},setSSO(t){return e.put(`/workspaces/current/sso`,t)},deleteSSO(){return e.delete(`/workspaces/current/sso`)}};export{t};